import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    MeshBasicMaterial,
    Color,
  } = THREE;

  const root = new Group();
  root.name = config.id || 'journal-card-3';

  const card = new Group();
  card.name = 'journal-card';
  root.add(card);

  const width = 1.9;
  const height = 1.19;
  const depth = 0.045;
  const accent = new Color('#ff2a38');

  const backingGeometry = new BoxGeometry(width, height, depth);
  const backingMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    roughness: 0.72,
  });
  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.name = 'surface-card';
  backing.position.z = -0.035;
  card.add(backing);

  const imageGeometry = new PlaneGeometry(width - 0.08, height - 0.08);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.96,
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'journal-image';
  imagePlane.position.z = 0.01;
  card.add(imagePlane);

  const edgeMaterial = new MeshBasicMaterial({
    color: accent,
    transparent: true,
    opacity: 0.95,
  });

  const edgeThickness = 0.025;
  const edgeDepth = 0.012;
  const edgeMeshes = [];

  const addEdge = (name, w, h, x, y, z) => {
    const geometry = new BoxGeometry(w, h, edgeDepth);
    const mesh = new Mesh(geometry, edgeMaterial);
    mesh.name = name;
    mesh.position.set(x, y, z);
    card.add(mesh);
    edgeMeshes.push(mesh);
    return mesh;
  };

  addEdge('accent-edge-top', width, edgeThickness, 0, height * 0.5 - edgeThickness * 0.5, 0.045);
  addEdge('accent-edge-bottom', width, edgeThickness, 0, -height * 0.5 + edgeThickness * 0.5, 0.045);
  addEdge('accent-edge-left', edgeThickness, height, -width * 0.5 + edgeThickness * 0.5, 0, 0.045);
  addEdge('accent-edge-right', edgeThickness, height, width * 0.5 - edgeThickness * 0.5, 0, 0.045);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items[0];

  if (textItem?.text) {
    const label = ctx.fontAtlas.createText(String(textItem.text), {
      fontSize: textItem.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left',
    });
    label.name = 'journal-card-label';
    label.position.set(-width * 0.5 + 0.16, -height * 0.5 + 0.16, 0.065);
    card.add(label);
  }

  let loadedTexture = null;
  let disposed = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture?.dispose?.();
        return;
      }
      loadedTexture = texture;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    card.position,
    { y: 0.15, z: 0 },
    { y: 0, z: 0, duration: 0.7, ease: 'power3.out' },
  );
  entrance.fromTo(
    card.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '<',
  );
  entrance.play();

  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(card.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out',
  });
  hoverTimeline.to(card.rotation, {
    x: -0.035,
    y: 0.045,
    duration: 0.3,
    ease: 'power2.out',
  }, '<');
  hoverTimeline.to(edgeMaterial, {
    opacity: 1,
    duration: 0.2,
    ease: 'power2.out',
  }, '<');

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(card.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'power2.out',
  });
  pressTimeline.to(card.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.24,
    ease: 'back.out(2)',
  });

  root.userData.handlers = {
    hover: () => {
      hoverTimeline.play();
    },
    pointerenter: () => {
      hoverTimeline.play();
    },
    pointerleave: () => {
      hoverTimeline.reverse();
    },
    blur: () => {
      hoverTimeline.reverse();
    },
    focus: () => {
      edgeMaterial.opacity = 1;
      hoverTimeline.play();
    },
    click: () => {
      pressTimeline.restart();
      ctx.emit('hub-journal.select', {
        id: config.id || 'journal-card-3',
        title: textItem?.text ? String(textItem.text) : 'Journal 3',
      });
    },
  };

  root.userData.cleanup = () => {
    disposed = true;

    entrance.kill();
    hoverTimeline.kill();
    pressTimeline.kill();

    loadedTexture?.dispose?.();

    backingGeometry.dispose();
    imageGeometry.dispose();
    backingMaterial.dispose();
    imageMaterial.dispose();

    for (const edge of edgeMeshes) {
      edge.geometry.dispose();
    }
    edgeMaterial.dispose();
  };

  return root;
}
